import pytest


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits, wrapping the high bits around.

    x is an int in 0..255 and k is an int in 0..7. The result is an int in
    0..255.
    """
    return ((x << k) | (x >> (8 - k))) & 0xFF


def test_rotl8_no_rotation() -> None:
    assert rotl8(0b10110001, 0) == 0b10110001
    assert rotl8(0, 0) == 0
    assert rotl8(255, 0) == 255


def test_rotl8_simple_shift() -> None:
    assert rotl8(0b00000001, 1) == 0b00000010
    assert rotl8(0b00000011, 2) == 0b00001100


def test_rotl8_wraps_high_bits() -> None:
    assert rotl8(0b10000000, 1) == 0b00000001
    assert rotl8(0b10000001, 1) == 0b00000011
    assert rotl8(0b11000000, 2) == 0b00000011
    assert rotl8(0b10110001, 4) == 0b00011011


def test_rotl8_max_k() -> None:
    assert rotl8(0b00000001, 7) == 0b10000000
    assert rotl8(0b00000010, 7) == 0b00000001
    assert rotl8(0b10000000, 7) == 0b01000000


def test_rotl8_fixed_points() -> None:
    for k in range(8):
        assert rotl8(0, k) == 0
        assert rotl8(255, k) == 255


@pytest.mark.parametrize("k", range(8))
def test_rotl8_result_in_range(k: int) -> None:
    for x in range(256):
        r = rotl8(x, k)
        assert 0 <= r <= 255


@pytest.mark.parametrize("k", range(8))
def test_rotl8_matches_string_rotation(k: int) -> None:
    for x in range(256):
        bits = format(x, "08b")
        expected = int(bits[k:] + bits[:k], 2)
        assert rotl8(x, k) == expected


@pytest.mark.parametrize("k", range(8))
def test_rotl8_preserves_popcount(k: int) -> None:
    for x in range(256):
        assert bin(rotl8(x, k)).count("1") == bin(x).count("1")


def test_rotl8_inverse_by_complement() -> None:
    for x in range(256):
        for k in range(8):
            assert rotl8(rotl8(x, k), (8 - k) % 8) == x


def test_rotl8_composes() -> None:
    for x in range(256):
        for a in range(8):
            for b in range(8):
                assert rotl8(rotl8(x, a), b) == rotl8(x, (a + b) % 8)
